Проблема в том, что вы неправильно применяете поворот камеры к позиции игрока. Вот исправленная версия функции:

```cpp
void addPlayersToRadar(Player * player) {
    Vector3 pos = player->position;
    Vector3 myPos = GetPosition(myPlayer);

    // Вычисляем вектор от нашего игрока к другому игроку
    Vector3 direction = pos - myPos;

    // Получаем расстояние
    float distance = Distancebyirc(myPos, pos);

    // Получаем угол поворота камеры (обычно это Y-компонента rotation)
    Quaternion cameraRotation = GetRotation(get_main());
    float cameraAngle = atan2(2.0f * (cameraRotation.w * cameraRotation.y + cameraRotation.x * cameraRotation.z),
                              1.0f - 2.0f * (cameraRotation.y * cameraRotation.y + cameraRotation.z * cameraRotation.z));

    // Или если у вас есть прямой доступ к углу поворота камеры:
    // float cameraAngle = GetCameraYaw(); // в радианах

    // Поворачиваем вектор направления относительно угла камеры
    float rotatedX = direction.x * cos(-cameraAngle) - direction.z * sin(-cameraAngle);
    float rotatedZ = direction.x * sin(-cameraAngle) + direction.z * cos(-cameraAngle);

    // Масштабируем для радара
    float radarScale = 180.0f; // максимальный радиус радара
    float scaleFactor = 1.0f;

    if (distance > radarScale) {
        scaleFactor = radarScale / distance;
    }

    // Применяем масштаб
    float radarX = rotatedX * scaleFactor;
    float radarZ = rotatedZ * scaleFactor;

    // Рисуем на радаре
    bg->AddCircleFilled({radar_center.x + radarX, radar_center.y - radarZ}, 5, ImColor(255, 0, 0, 255));
}
```

Альтернативный вариант с использованием матрицы поворота:

```cpp
void addPlayersToRadar(Player * player) {
    Vector3 pos = player->position;
    Vector3 myPos = GetPosition(myPlayer);

    // Вектор от нас к игроку
    Vector3 toPlayer = pos - myPos;

    // Получаем матрицу поворота камеры (только по Y оси)
    float cameraYaw = GetCameraYaw(); // предполагаем, что это в радианах

    // Создаем матрицу поворота для Y оси
    float cosYaw = cos(-cameraYaw);
    float sinYaw = sin(-cameraYaw);

    // Применяем поворот
    float rotatedX = toPlayer.x * cosYaw - toPlayer.z * sinYaw;
    float rotatedZ = toPlayer.x * sinYaw + toPlayer.z * cosYaw;

    // Ограничиваем расстояние для радара
    float distance = sqrt(rotatedX * rotatedX + rotatedZ * rotatedZ);
    float maxRadarDistance = 180.0f;

    if (distance > maxRadarDistance) {
        float scale = maxRadarDistance / distance;
        rotatedX *= scale;
        rotatedZ *= scale;
    }

    // Позиция на радаре (инвертируем Z для правильного отображения)
    ImVec2 radarPos = {
        radar_center.x + rotatedX,
        radar_center.y - rotatedZ  // минус, потому что Y идет вниз в UI
    };

    bg->AddCircleFilled(radarPos, 5, ImColor(255, 0, 0, 255));
}
```

Ключевые моменты:
1. Вычисляем вектор направления от нашего игрока к целевому
2. Применяем поворот камеры к этому вектору (обычно только по оси Y)
3. Масштабируем результат для отображения на радаре
4. Инвертируем Z координату при отрисовке, так как в UI системе Y растет вниз

